import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"Host API v1alpha3","description":"","frontmatter":{},"headers":[],"relativePath":"spec/host-api/v1alpha3.md","filePath":"spec/host-api/v1alpha3.md"}'),s={name:"spec/host-api/v1alpha3.md"};function i(r,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="host-api-v1alpha3" tabindex="-1">Host API v1alpha3 <a class="header-anchor" href="#host-api-v1alpha3" aria-label="Permalink to &quot;Host API v1alpha3&quot;">​</a></h1><p><code>forms.takoform.com/v1alpha3</code> is the current Host API lane (<a href="./../decisions/0013-v1alpha3-lane-ships-in-provider-v2-1.html">decision 0013</a>). It carries namespaced FormRef groups, UID/generation/revision resource identity, long-running Operations, content-addressed artifact upload, and Host Support Profiles. The retained v1alpha2 contract in <a href="./"><code>README.md</code></a> continues to govern the frozen provider-v2 lane; rules stated there and not changed here (space identity, I-JSON raw-first decoding, idempotency-key namespacing, replay fingerprinting, same-origin endpoint negotiation) apply to this lane unchanged.</p><p>The wire schema is <a href="/schemas/v1alpha3/host-api-wire.schema.json"><code>../schemas/host-api-wire-v1alpha3.schema.json</code></a>; the machine operation table is <a href="operations-v1alpha3.json"><code>operations-v1alpha3.json</code></a>.</p><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h2><p><code>GET /.well-known/takoform/v1alpha3</code> returns a document validating against <a href="/schemas/v1alpha3/host-discovery.schema.json"><code>../schemas/host-discovery-v1alpha3.schema.json</code></a>: <code>api_versions</code> is exactly <code>[&quot;forms.takoform.com/v1alpha3&quot;]</code>; the features <code>service_forms</code>, <code>exact_form_ref</code>, <code>optimistic_concurrency</code>, <code>idempotent_lifecycle</code>, <code>operations</code>, <code>artifact_upload</code>, and <code>support_profiles</code> are all required and true; <code>endpoints.api</code> is same-origin with path <code>/apis/forms.takoform.com/v1alpha3</code>. Each lane has its own discovery path; a v1alpha2 client can never select this lane accidentally.</p><p>Every advertised endpoint path is compared in its escaped form and MUST carry no percent-encoding at all. A client rejects the discovery document otherwise (<a href="./../decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>): an escaped path describes a shape this lane does not have, and comparing the decoded path instead would let <code>%2Fv1alpha3</code> pass as <code>/v1alpha3</code>.</p><p>A client negotiates each lane independently, under a deadline of its own that is short and separate from its resource-operation deadline. Nothing about one lane&#39;s outcome may make another lane&#39;s resources unusable, and each resource type reports its own lane&#39;s negotiation error.</p><h2 id="path-shape" tabindex="-1">Path shape <a class="header-anchor" href="#path-shape" aria-label="Permalink to &quot;Path shape&quot;">​</a></h2><p>A namespaced Form group travels as <strong>two ordinary path segments</strong> — the group name, then the group version — wherever a URL template names a group:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{api}/resources/{formGroup}/{formVersion}/{kind}/{name}</span></span>
<span class="line"><span>{api}/form-definitions/{formGroup}/{formVersion}/{kind}</span></span>
<span class="line"><span>{api}/support/forms/{formGroup}/{formVersion}/{kind}/{definitionVersion}</span></span></code></pre></div><p>So <code>edge.forms.takoform.com/v1alpha1</code> travels as <code>edge.forms.takoform.com/v1alpha1</code>. <strong>No path segment ever percent-encodes a slash.</strong> Proxies, gateways, and web frameworks disagree about whether <code>%2F</code> inside a path segment is passed through, decoded, rejected, or normalized, so a lane that required it could not be placed behind ordinary infrastructure at all (<a href="./../decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>). A host rejoins the two segments into the exact apiVersion; the FormRef <code>apiVersion</code> string is unchanged everywhere else — request bodies, responses, and the <code>group</code> query key still carry <code>edge.forms.takoform.com/v1alpha1</code> verbatim. This is the required conformance check <code>namespaced-group-travels-as-two-path-segments</code>.</p><h2 id="resource-identity" tabindex="-1">Resource identity <a class="header-anchor" href="#resource-identity" aria-label="Permalink to &quot;Resource identity&quot;">​</a></h2><ul><li><code>metadata.name</code> is the only name; Form desired schemas do not carry a <code>name</code> field.</li><li><code>metadata.uid</code> is host-issued and immutable. Delete followed by re-create of the same name yields a new UID. A client MAY fence any mutation with <code>expectedUid</code>; mismatch fails <code>uid_mismatch</code> (409).</li><li><code>metadata.generation</code> increments only when the portable desired spec changes. Desired-state mutations fence on the expected generation (<code>Takoform-Expected-Generation</code> header or <code>expectedGeneration</code> body field); a stale fence fails <code>generation_conflict</code> (412).</li><li><code>metadata.revision</code> increments whenever the representation — including status, conditions, and outputs — changes. The strong ETag is the quoted revision; <code>If-Match</code> fences on it and a stale value fails <code>revision_conflict</code> (412).</li><li><strong>A <code>delete</code> fences on the expected generation, and MUST NOT be required to fence on the revision.</strong> A delete withdraws desired state, so it is a desired-state mutation and carries the same fence every other one carries: the <code>Takoform-Expected-Generation</code> header, REQUIRED, with a stale value failing <code>generation_conflict</code> (412) and an absent one <code>invalid_argument</code> (400). A client MAY additionally send <code>If-Match</code>, and a host that is given one MUST honor it and answer <code>revision_conflict</code> (412) when the representation moved — but a host MUST NOT require it, and MUST NOT refuse an otherwise valid delete because the revision moved. The revision moves for reasons the deleting client did not cause: a host-side status change, and the derived rendering below. Removing an aggregate means removing its dependents first, so a client&#39;s own teardown moves the revision of the resource it is about to delete next, after the plan that computed the teardown read it — and requiring the representation fence would refuse a destroy on a change the destroy itself made, with no repair available, because the next dependent moves it again. The generation moves only when a client changes a desired spec, which is the only &quot;it changed under me&quot; a deleter can act on; the incarnation question is <code>expectedUid</code>&#39;s, and an accepted delete resolves through the recorded uid before it evaluates any fence. These are the required conformance checks <code>delete-generation-fence</code> and <code>delete-fence-survives-derived-rendering</code>, and they are decided by <a href="./../decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>.</li><li>A host that renders any part of a representation from OTHER resources MUST advance that resource&#39;s <code>metadata.revision</code> when the rendering changes, and MUST NOT move its <code>metadata.generation</code>: no desired spec changed. This lane has two such renderings — relation drift and Worker readiness — so creating, re-weighting, or deleting a <code>WorkerDeployment</code> moves the revision of the <code>ModuleWorker</code> whose readiness follows it, and a target that is deleted or replaced moves the revision of every source pinned to it. Serving the changed representation under the old revision would make the ETag a validator that reports &quot;unchanged&quot; about a change, and <code>If-Match</code> a fence on a representation the client never saw. After an accepted mutation a host recomputes the rendering of every resource that mutation can affect and advances only those that actually changed, so an idempotent re-apply moves nothing anywhere. This is a required conformance check (<code>dependent-revision-advances-with-rendering</code>), and it is decided by <a href="./../decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>. It is also exactly why a delete does not fence on the revision, above: the rendering a teardown moves is the rendering of what the teardown deletes next.</li><li><code>status.observedGeneration</code> names the desired generation the status reflects; <code>status.conditions</code> uses the closed types <code>Ready</code>, <code>Reconciling</code>, <code>Degraded</code>, <code>Drifted</code>, <code>Blocked</code>, <code>Deleting</code> with closed portable reasons and an optional non-portable <code>hostReason</code>. A client surfaces the WHOLE condition list, not a boolean derived from it: the reason is what says why a resource is not ready, and a client that discards it forces its operator to leave the tool to find out (<a href="./../decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>). Conditions are host-rendered state that changes without any desired spec changing, so a client MUST NOT carry a previous value forward as if it were still true.</li><li><strong>A replay record does not outlive the incarnation it reports.</strong> A host MUST NOT answer a request from a recorded idempotency replay once the incarnation that recording reports as LIVE no longer exists; such a record is RETIRED and the request is executed as the new request it is. A record is bound to the <code>metadata.uid</code> its recorded answer carries — a create, an update, an adoption, and an observe all report one. A record whose answer reports no live incarnation is bound to nothing and MUST keep replaying: that is a successful delete, whose <code>204</code> reports the incarnation gone, and every refusal. An accepted <code>202</code> is bound to its Operation and follows that operation&#39;s outcome. Retirement is by INCARNATION, never by name: a later resource taking the same name retires nothing, and a host MAY still expire records by age or capacity. Both halves matter. Without retirement a <code>destroy</code> followed by an <code>apply</code> of an unchanged configuration is answered the old <code>201</code> forever and never converges, because a create&#39;s prepare binds the create markers so the re-create derives a byte-identical key and fingerprint; retire a delete&#39;s own record and the retried delete of a lost response is EXECUTED against whichever incarnation holds the name now. These are the required conformance checks <code>apply-idempotency-replay</code> and <code>replay-record-retires-with-its-incarnation</code>, and they are decided by <a href="./../decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>.</li><li>The Form semantic identity is the exact FormRef. The package digest used at installation is audit evidence (<code>form.packageDigest</code>, optional in responses); it never enters queries, fences, or state identity, and a host that installed the same FormRef from a different legitimate package MUST read and delete the same resources.</li><li>An exact FormRef query is answered about the WHOLE identity or not at all. A host MUST fail <code>form_unknown</code> (404) when the <code>definitionVersion</code> or <code>schemaDigest</code> it was given names a definition it does not have, on <code>{api}/forms</code>, on <code>{api}/form-definitions/…</code>, and on every resource route — it MUST NOT fall back to matching the group and kind. A client dispatches on the exact FormRef recorded in its state precisely so that a resource created under an earlier definition version stays addressable as itself (<a href="./../decisions/0017-provider-state-survives-form-evolution-and-interruption.html">decision 0017</a>), and a host that matched by kind would answer every such request about a different contract, successfully, with nothing downstream able to detect it. This is the required conformance check <code>exact-form-ref-fails-closed-on-unknown-definition</code>.</li></ul><h3 id="the-installed-set-is-keyed-by-the-exact-identity" tabindex="-1">The installed set is keyed by the exact identity <a class="header-anchor" href="#the-installed-set-is-keyed-by-the-exact-identity" aria-label="Permalink to &quot;The installed set is keyed by the exact identity&quot;">​</a></h3><p>The rules of this section are decided by <a href="./../decisions/0022-relations-pin-the-target-contract.html">decision 0022</a>.</p><ul><li>A host&#39;s installed set is keyed by the whole <code>{apiVersion, kind, definitionVersion, schemaDigest}</code> tuple, never by group and kind. Two definition versions of one group and kind MUST be installable at the same time and MUST answer independently on <code>{api}/forms</code>, on <code>{api}/form-definitions/…</code>, and on <code>{api}/support/forms/…</code>. A host MUST NOT install two Definitions that agree on group, kind, and <code>definitionVersion</code> and differ on <code>schemaDigest</code>: a definition version names one set of bytes, and the support path resolves an exact identity from that version alone. A <code>definitionVersion</code> from one contract combined with a <code>schemaDigest</code> from another names no installed Definition and fails <code>form_unknown</code> (404) like any other unknown identity. This is the required conformance check <code>two-definition-versions-answer-independently</code>.</li><li>A resource RECORDS the exact FormRef it was created under. That ref is written at create, carried forward unchanged by every update and import, and is the only identity the resource is answered about. A <code>read</code>, <code>observe</code>, <code>apply</code>, <code>import</code>, or <code>delete</code> naming any other exact ref addresses no resource and fails <code>resource_not_found</code> (404) — the Form may well be installed; what is absent is a resource of that name under that contract. A response MUST NOT rewrite an older resource&#39;s recorded ref to a newer one. This is the required conformance check <code>resource-answers-only-under-its-recorded-form-ref</code>.</li><li>A resource NAME stays unique within one tenant, space, group, and kind. The definition version decides what a request is answered about, never where a resource lives: a reference is <code>{apiVersion, kind, name}</code> and carries no definition version, so two same-named resources of one kind under different contracts would leave every reference to that name unresolvable. A create therefore still conflicts with a name taken under another contract of the same kind — and never with a name taken by another TENANT, which is a different address entirely (<a href="#tenant-isolation">Tenant isolation</a>).</li></ul><h2 id="tenant-isolation" tabindex="-1">Tenant isolation <a class="header-anchor" href="#tenant-isolation" aria-label="Permalink to &quot;Tenant isolation&quot;">​</a></h2><p>The rules of this section are decided by <a href="./../decisions/0028-the-resource-plane-is-tenant-isolated.html">decision 0028</a>.</p><p>A host&#39;s <strong>internal resource address MUST include the tenant, the space, the <code>apiVersion</code>, the <code>kind</code>, and the <code>name</code>.</strong> The tenant is the AUTHENTICATED tenant of the request: no path segment, query key, reference, or <code>metadata</code> member names one, so it comes from the credential and from nowhere else. It is recorded when a resource is created and carried forward by every update and import, exactly like the recorded exact FormRef.</p><p>A request that carries no credential, or one naming nobody, therefore has no tenant and MUST be refused <code>unauthenticated</code> (401) — never <code>permission_denied</code> (403), because the caller has not been identified and there is nothing yet to deny. This is the required conformance check <code>unauthenticated-request-refused</code>, driven with an ABSENT <code>Authorization</code> header and with a well-formed bearer credential naming nobody, on a read surface and on a mutating one. Everything below is downstream of it: a host whose credential lookup fails open has picked a tenant the caller never named, and every rule in this section is then about a boundary that is not there.</p><p>Everything else follows from the address.</p><ul><li>Two tenants MAY create one <code>{space, apiVersion, kind, name}</code>. They get two resources with two host-issued uids, two generations, and two revisions. Neither create conflicts with the other, because a name is taken <strong>within one tenant</strong> — a host that let one tenant&#39;s name choice deny another&#39;s would make the whole name space a shared, first-come resource and a membership oracle besides.</li><li>Every surface that takes a resource name addresses the caller&#39;s own tenant: <code>read</code>, <code>observe</code>, <code>prepare</code>, <code>apply</code>, <code>import</code>, and <code>delete</code>. A request naming another tenant&#39;s resource is answered exactly as one naming a resource that was never created. Where that answer is a refusal it is <code>resource_not_found</code> (404), and it MUST be <strong>indistinguishable</strong> from the refusal for a name nobody created — the same code, the same status, and a message that discloses nothing about the other tenant. <code>permission_denied</code> (403) is the wrong answer and is forbidden here: it would confirm that a resource of that name exists somewhere on the host, which is the fact the boundary exists to withhold, to any caller who can guess a name.</li><li><strong>&quot;Its own tenant&quot; is a permission as well as a limit.</strong> Every tenant MUST be able to create, read, observe, update, import, and delete resources in its own plane, and a resource MUST stay operable by its holder after a caller from another tenant has been refused. A host that is create-and-read-only outside one privileged tenant, and a host that quarantines a record a stranger reached for, both refuse everything the paragraph above requires them to refuse — and both have taken a resource from the tenant that owns it. Required conformance checks: <code>each-tenant-mutates-its-own-plane</code>, and the holder&#39;s own leg of <code>resource-update-is-tenant-isolated</code> and <code>resource-delete-is-tenant-isolated</code>.</li><li><code>import</code> is the one surface whose absent answer is not a refusal, so the rule is stated for it exactly. An adoption under <code>If-None-Match: *</code> of a name the caller does not hold MINTS a resource at generation 1, and a name held only by another tenant is not held by the caller — so that adoption MUST succeed, and MUST answer what the same adoption of a name nobody holds anywhere answers: the same status, the same ETag, and a document differing in nothing but the host-issued uid and the name. An adoption carrying an update generation fence names an existing resource instead, so against a name only another tenant holds it fails <code>resource_not_found</code> (404) like any other absent target. A host that refused the create-intent adoption with <code>generation_conflict</code> would be answering &quot;that name is taken&quot; about a tenant the caller cannot see; one that took the update path would write the caller&#39;s desired state over a stranger&#39;s live resource, which — followed by a delete — destroys it through nothing but a name.</li><li><code>validate</code> carries a name and resolves none: it answers diagnostics about the document it was handed and reads no stored resource, so it has no tenant-dependent answer to give.</li><li><strong>Relations resolve only within the same tenant, and the stored pin is the uid they resolved to.</strong> A reference is <code>{apiVersion, kind, name}</code> and carries neither a tenant nor a space, so it is resolved inside the referring resource&#39;s own scope. A name that only another tenant holds is an absent target and fails <code>resource_not_found</code> (404) like any other. Resolving correctly and PINNING the other tenant&#39;s uid is the same defect arriving one step later, and it is the step everything downstream reads: deletion protection, drift, and every Worker aggregate rule are computed from the pin, so a foreign pin protects one tenant&#39;s resource from its own owner and makes another tenant&#39;s source follow a resource its author never named. A host that resolved a reference across tenants would bind one tenant&#39;s desired state to another tenant&#39;s resource and pin its uid into stored state, which is the substitution <a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a> closes for incarnations, committed across a security boundary rather than a naming one. Deletion protection, drift, and every Worker aggregate rule read those pinned relations, so all of them stop at the tenant too.</li><li>A <code>prepareDigest</code> is minted for one tenant and is spendable by that tenant alone. An apply presenting a review minted in another tenant fails <code>invalid_argument</code> (400) before any mutation — the ordinary prepare-binding refusal, because the resource being addressed is the caller&#39;s own and what is untrue is the review. A create binding pins no uid and no generation, so without the tenant two tenants preparing one name in one space would hold the same digest, and a review — a value clients log, print in plans, and pass between processes — would be a bearer token over another tenant&#39;s plane. The boundary is the TENANT and not the principal: a second principal of the minting tenant MUST be able to spend the same review, because planning under one identity and applying under another is ordinary operation and a host enforcing the rule more tightly than it is written is a host two deployments differ on.</li><li>An <code>Idempotency-Key</code> names one operation <strong>of one tenant</strong>. The same key from two tenants is two operations, and each tenant replays only its own recorded response. Answering a second tenant with the first tenant&#39;s recorded success would hand it another tenant&#39;s uid, generation, and ETag while performing no mutation at all — and so would answering it a fresh-looking <code>201</code> that stores nothing, which is why the check reads the second tenant&#39;s resource back.</li><li>Anything a host renders from OTHER resources — the relation drift and Worker readiness of <a href="#resource-identity">Resource identity</a> — is computed from, and advances the revision of, resources of the mutating tenant only. That pass writes, so a host-wide one would move another tenant&#39;s ETag.</li></ul><p>There is <strong>one deliberate exception</strong>, and it is the one <a href="./../decisions/0026-attachment-claims-are-canonical-and-acyclic.html">decision 0026</a> already decided: a <code>WorkerCustomDomain</code>&#39;s canonical hostname is unique across every space <strong>of one tenant</strong>, because spaces partition one tenant&#39;s resources and DNS does not partition with them (<a href="#an-attachment-s-claim-is-decided-on-canonical-resolved-identity">An attachment&#39;s claim is decided on canonical, resolved identity</a>). That rule drops the space and keeps the tenant. It does not reach past the tenant, and no rule in this lane does.</p><p>Ten required conformance checks measure this, all of them black box, all of them driven with two configured tenants&#39; credentials: <code>resource-address-is-tenant-scoped</code>, <code>resource-read-is-tenant-isolated</code>, <code>resource-observe-is-tenant-isolated</code>, <code>resource-update-is-tenant-isolated</code>, <code>resource-import-is-tenant-isolated</code>, <code>resource-delete-is-tenant-isolated</code>, <code>relation-resolution-is-tenant-scoped</code>, <code>prepare-is-tenant-scoped</code>, <code>idempotency-is-tenant-scoped</code>, and <code>each-tenant-mutates-its-own-plane</code>. A runner that cannot authenticate as two tenants can measure none of them, which is why the lane&#39;s runner REQUIRES an alternate-tenant credential alongside the same-tenant alternate principal rather than treating it as optional.</p><p>Nine of the ten are enumerated by SURFACE and not by intent. Every route of <a href="#lifecycle">Lifecycle</a> that takes a resource name is listed against the check that measures it, and the list is bound to the published route block, to the reference host&#39;s router, and to the required-check list by tests, so a name-addressed endpoint cannot be added to this lane without one. An enumeration by intent is what left <code>observe</code> and <code>import</code> out of the first version of this section: both take a name, one returns a whole representation and one mutates, and a host that scoped <code>read</code>, <code>apply</code> and <code>delete</code> while resolving either host-wide satisfied every check there was. The tenth is not a surface but the permissive half of all of them, so it is listed against <code>PUT</code> and <code>DELETE</code> beside the two boundary checks it completes.</p><p>Two facts are host obligations this lane does NOT prove, because a black-box runner cannot observe them:</p><ul><li>that the tenant is part of the ADDRESS rather than a filter applied somewhere late. The checks measure the consequences, which is what a third-party host can be held to; a host that reaches the same answers by other means passes, and is conforming.</li><li>that a host-wide derived-rendering pass would cross the tenant. Constructing the case needs one tenant&#39;s resource to render from another&#39;s, and relation resolution refuses to build it — so there is no request sequence that distinguishes a scoped pass from an unscoped one.</li></ul><p>Publication blocker <strong>V3-012</strong> records this item; the reference host&#39;s own obligations are proved by host-side tests in <code>internal/portableconformancev3/tenant_isolation_test.go</code>.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>Endpoints under <code>/apis/forms.takoform.com/v1alpha3</code>, keyed by group and kind so one kind name can exist in many groups. <code>{formGroup}/{formVersion}</code> is the two-segment group of <a href="#path-shape">Path shape</a>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    {api}/forms?space&amp;group&amp;kind&amp;definitionVersion&amp;schemaDigest</span></span>
<span class="line"><span>GET    {api}/form-definitions/{formGroup}/{formVersion}/{kind}?…</span></span>
<span class="line"><span>POST   {api}/resources/validate         diagnostics only, no mutation, no digest</span></span>
<span class="line"><span>POST   {api}/resources/prepare          short-lived prepare digest for one exact spec</span></span>
<span class="line"><span>PUT    {api}/resources/{formGroup}/{formVersion}/{kind}/{name}    apply; carries review.prepareDigest</span></span>
<span class="line"><span>GET    {api}/resources/{formGroup}/{formVersion}/{kind}/{name}</span></span>
<span class="line"><span>POST   {api}/resources/{formGroup}/{formVersion}/{kind}/{name}/import</span></span>
<span class="line"><span>POST   {api}/resources/{formGroup}/{formVersion}/{kind}/{name}/observe</span></span>
<span class="line"><span>DELETE {api}/resources/{formGroup}/{formVersion}/{kind}/{name}</span></span></code></pre></div><p><code>observe</code> is the lane&#39;s only fenced read-only re-observation. There is no <code>refresh</code> operation: v1alpha2 carried both under one contract, which meant two spellings of one behavior and therefore two ways for hosts to differ. A v1alpha3 Form never declares the <code>refresh</code> capability and a v1alpha3 host serves no <code>/refresh</code> route.</p><p><code>validate</code> reports diagnostics without mutating and without minting a digest; a client MUST NOT describe provider apply-time preparation as &quot;reviewed in plan&quot;. <code>prepare</code> binds the exact spec, identity, and fences to a <code>prepareDigest</code> the way v1alpha2 <code>preview</code> binds a plan digest; substitution after prepare fails <code>invalid_argument</code> before mutation.</p><p><code>delete</code> carries an empty body, an <code>Idempotency-Key</code>, and the expected generation, which is its only required precondition (<a href="#resource-identity">Resource identity</a>).</p><p>Role rules are wire-enforced: an update to a <code>revision</code>-role resource fails <code>invalid_argument</code>; deleting a resource any live relation references fails <code>dependency_in_use</code> (409); deleting a <code>deployment</code>-role resource any live dependent needs fails the same way (<a href="./../decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>); a resource protected by policy fails <code>deletion_protected</code> (409).</p><h2 id="cross-resource-relations" tabindex="-1">Cross-resource relations <a class="header-anchor" href="#cross-resource-relations" aria-label="Permalink to &quot;Cross-resource relations&quot;">​</a></h2><p>The rules of this section are decided by <a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>.</p><p>A <strong>relation</strong> is one reference from a resource&#39;s desired spec to another resource. Its wire shape is the closed three-member object</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.forms.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EdgeKVNamespace&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>where <code>apiVersion</code> and <code>kind</code> are <code>const</code> in the referring Form&#39;s <code>desiredSchema</code> and <code>name</code> follows the portable resource-name grammar. Both constants are required. A reference carrying only <code>{kind, name}</code> cannot address two Form Families at once and forces a host to guess which installed Form a bare kind means; a group-qualified reference makes the target Form exact.</p><p>Relations are <strong>derived from the Form Definition&#39;s <code>desiredSchema</code>, never declared</strong>. Every reference already states its target group and kind as schema constants, so a separate relation list on the Definition would be a second source of truth for facts the schema already carries — and the published Form Definition schema admits no such member (<a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>). A host derives the relation set from the same <code>desiredSchema</code> it serves: every closed object that requires exactly <code>apiVersion</code>, <code>kind</code>, and <code>name</code> with the first two <code>const</code> is a relation, identified by its JSON Pointer with <code>*</code> standing for an array element (<code>/worker</code>, <code>/versions/*/workerVersion</code>, <code>/kvBindings/*/resource</code>). A binding-list property additionally carries the <code>x-takoform-binding</code> annotation naming the Binding contract that governs the references inside it; the exact digest-bound BindingRef is the Definition&#39;s own <code>acceptedBindings</code> entry of that name.</p><h3 id="what-a-relation-requires-of-its-target" tabindex="-1">What a relation requires of its target <a class="header-anchor" href="#what-a-relation-requires-of-its-target" aria-label="Permalink to &quot;What a relation requires of its target&quot;">​</a></h3><p>The rules of this section are decided by <a href="./../decisions/0022-relations-pin-the-target-contract.html">decision 0022</a>.</p><p>A group and a kind say WHICH resource a reference names. They say nothing about what that resource must still satisfy, so a target whose Definition later moved to an incompatible version would keep satisfying every reference to it. Every reference-shaped node in a <code>desiredSchema</code> therefore carries exactly one target contract, as an annotation on the reference itself — data the published Form Definition schema already admits, exactly like <code>x-takoform-binding</code> (<a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;x-takoform-target-formrefs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.forms.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WorkerBundle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;definitionVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>when the relation depends on the target&#39;s exact desired contract, or</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;x-takoform-required-interface&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;interfaces.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;worker.runtime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>when it depends only on an Interface the target provides. A reference carrying both, or neither, is refused when relations are derived: a host that cannot say what a relation requires cannot verify it.</p><p>Which one is correct is decided by the dependency, not by preference. <code>x-takoform-target-formrefs</code> states the requirement when the source — or the host acting for it — reads a member of the target&#39;s desired spec, or enforces a rule stated over the target Form itself: a <code>WorkerVersion</code>&#39;s <code>/bundle</code>, whose <code>manifestDigest</code> a host resolves to learn what the version runs; a <code>WorkerDeployment</code>&#39;s <code>/versions/*/workerVersion</code>, whose <code>handlers</code> and <code>/worker</code> relation decide what the deployment serves and owns; and a <code>WorkerDeployment</code>&#39;s <code>/worker</code>, the one reference that WRITES to its target, because a deployment is what renders a Module Worker&#39;s readiness under <a href="./../decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>. <code>x-takoform-required-interface</code> states it everywhere else, including every typed binding and every inward-activation attachment, because what those need is the behavior a contract fixes and any Form providing it would serve.</p><p>A binding-list reference MUST require exactly the Interface its Binding Definition names as <code>targetInterface</code>. The Binding Definition stays the authority and the annotation is its projection onto the reference, so the two cannot become two sources of truth; a binding relation is verified against its Binding Definition first, in the order below, and against the annotation second.</p><h3 id="resolution-and-uid-pinning" tabindex="-1">Resolution and UID pinning <a class="header-anchor" href="#resolution-and-uid-pinning" aria-label="Permalink to &quot;Resolution and UID pinning&quot;">​</a></h3><p>On <code>apply</code> and <code>import</code>, for every derived relation present in the materialized spec, a host MUST, before any mutation (<a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>):</p><ul><li>resolve <code>(space, apiVersion, kind, name)</code> to a stored resource. Absent fails <code>resource_not_found</code> (404) and the message MUST name the relation pointer. Cross-space references are unrepresentable — a reference carries no space.</li><li>verify that the resolved resource&#39;s Form has exactly the referenced group and kind, failing <code>invalid_argument</code> (400) on mismatch. The resolved resource&#39;s own RECORDED exact ref names that Form; a well-formed spec cannot reach this, because the schema pins both constants, but a host that resolved by name alone can, and must refuse rather than bind the wrong Form.</li><li>verify the target contract the reference annotates (<a href="./../decisions/0022-relations-pin-the-target-contract.html">decision 0022</a>): the target&#39;s recorded exact ref is one of the listed <code>x-takoform-target-formrefs</code>, or the target Form&#39;s Definition declares the annotated <code>x-takoform-required-interface</code> in <code>providedInterfaces</code> at exactly that digest. A target that satisfies neither fails <code>invalid_argument</code> (400) — the request is well formed and states something untrue about the resource it points at — and the message MUST name the relation pointer and what was required. These are the required conformance checks <code>relation-target-form-ref-verified</code> and <code>relation-target-interface-verified</code>.</li><li>verify the binding contract when the relation is a binding (below).</li><li>record the resolution as <code>{pointer, relation, targetAPIVersion, targetKind, targetName, targetUID, targetFormRef, bindingRef?}</code> alongside the resource, where <code>pointer</code> is the concrete instance pointer and <code>relation</code> is the derived pointer it came from.</li></ul><p>A host MUST store the <strong>target UID</strong>, not only the name. A name is a label the client chose and can reuse; the UID is the identity of one incarnation. It MUST also store the <strong>target&#39;s exact FormRef</strong>: the UID pins which incarnation the source is bound to, and the ref pins what contract that incarnation satisfies. This is the required conformance check <code>relation-pin-records-target-form-ref</code>.</p><h3 id="incarnation-change" tabindex="-1">Incarnation change <a class="header-anchor" href="#incarnation-change" aria-label="Permalink to &quot;Incarnation change&quot;">​</a></h3><p>When a resource is read or observed and a stored relation&#39;s target now resolves to a <em>different</em> UID, to a different exact FormRef, or to nothing, the source reports <code>Ready=False</code> with</p><ul><li><code>ExternalChange</code> — the target name resolves to a different incarnation, or the same incarnation under a different exact contract;</li><li><code>DependencyMissing</code> — the target no longer exists;</li></ul><p>and a <code>hostReason</code> naming the relation pointer, both UIDs, and both exact FormRefs. A host MUST NOT re-bind the relation automatically: re-resolving the name would make a delete and re-create of the target invisible and silently point the source at a resource its author never named. The source stays pinned until it is re-applied, and re-reading it does not heal the condition. A moved CONTRACT is reported through this same condition rather than a parallel one: it is the same fact — the source is pinned to something that is no longer there — with the same remedy.</p><h3 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h3><p>The remedy is an apply, and it MUST stay reachable (<a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>).</p><ul><li><strong>What the host reports.</strong> The condition above, on <code>read</code> and <code>observe</code>, for as long as the stored relation does not resolve to its pinned UID. Reporting it is not an error outcome: the resource is still readable, still deletable, and still carries its desired spec.</li><li><strong>What re-pins.</strong> Every ACCEPTED mutation re-resolves every relation and stores the UIDs it resolved to, including a <code>apply</code> whose spec is byte-identical to the stored one. Re-pinning is host-owned bookkeeping, not desired state: it MUST NOT move <code>metadata.generation</code>, and it moves <code>metadata.revision</code> exactly when it changes the representation the host serves — which it does, because the Ready condition stops reporting the drift. A second identical apply then moves nothing at all.</li><li><strong>What a client must do.</strong> Report the break without failing the read, and offer an apply. A client that fails its refresh on this condition removes its own remedy, because the plan that repairs the resource is computed from the refreshed state. A Form that declares <code>update</code> recovers with a spec-identical apply. A Form that declares none — every <code>revision</code>-role Form — has no such apply at all: a host refuses every apply to the existing resource, so its only recovery is REPLACEMENT, and a client MUST plan one. A <code>DependencyMissing</code> target must exist again before either apply can succeed.</li></ul><p>A client sees the same fact — an incarnation changed — in two places, and the two answers differ because the remedies do. A relation whose TARGET moved is a warning with a proposed apply: the resource itself is still the one state names, and an accepted apply re-pins the reference. A resource whose OWN <code>metadata.uid</code> no longer matches what state records is an error the operator must resolve, and a client MUST keep the resource in state while reporting it: no apply converts one incarnation into another, and dropping the resource would make the next apply fence on <code>If-None-Match: *</code> against the resource that does exist, with no plan left that repairs anything (<a href="./../decisions/0017-provider-state-survives-form-evolution-and-interruption.html">decision 0017</a>).</p><h3 id="dependency-protection" tabindex="-1">Dependency protection <a class="header-anchor" href="#dependency-protection" aria-label="Permalink to &quot;Dependency protection&quot;">​</a></h3><p>Deleting a resource that any stored relation references by UID fails <code>dependency_in_use</code> (409). This covers every relation, not only typed bindings: a Worker Bundle a Worker Version executes, a Worker Version a Worker Deployment weights, a Module Worker an attachment activates, a queue a consumer drains, and a dead-letter queue are all live dependencies. A resource that references itself does not block its own deletion. An accepted (202) delete re-runs the scan at commit time against the incarnation it was accepted for, so a resource that acquired a holder while the operation was pending survives, and a resource that merely took the deleted one&#39;s name is never touched.</p><h3 id="binding-verification" tabindex="-1">Binding verification <a class="header-anchor" href="#binding-verification" aria-label="Permalink to &quot;Binding verification&quot;">​</a></h3><p>A binding relation is verified, never assumed. Before any mutation a host MUST check, in this order:</p><ol><li>the source Form Definition&#39;s <code>acceptedBindings</code> carries the Binding contract the desired schema annotates — otherwise <code>invalid_argument</code> (400);</li><li>the host has installed that contract at exactly the accepted <code>schemaDigest</code> — otherwise <code>unsupported_capability</code> (422), because the capability itself is unavailable rather than the request malformed;</li><li>the source Form&#39;s <code>role</code> equals the Binding Definition&#39;s <code>sourceRole</code> — otherwise <code>invalid_argument</code> (400);</li><li>the resolved target&#39;s exact Form (group and kind) appears in the Binding Definition&#39;s <code>allowedTargetForms</code> — otherwise <code>invalid_argument</code> (400);</li><li>the target Form&#39;s Definition declares the Binding&#39;s <code>targetInterface</code> in <code>providedInterfaces</code> — otherwise <code>invalid_argument</code> (400). A binding projects an Interface, so a target that provides none cannot be bound;</li><li>source and target share a space, which the wire guarantees: a reference carries no space member.</li></ol><p>Rules 3 through 5 are about the target or holder the client chose and are therefore argument failures; rule 2 is about what this host can do at all.</p><h2 id="the-worker-aggregate" tabindex="-1">The Worker aggregate <a class="header-anchor" href="#the-worker-aggregate" aria-label="Permalink to &quot;The Worker aggregate&quot;">​</a></h2><p>The rules of this section are decided by <a href="./../decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>. They are semantics a desired-state schema cannot express — a schema cannot count the deployments pointing at one worker, read the <code>/worker</code> relation of a version it does not contain, add weights, know which handlers a referenced version exports, or reach across sibling properties — so they live in the host under <a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a> and are proven by required conformance checks.</p><p>A <strong>Worker aggregate</strong> is one <code>ModuleWorker</code> incarnation, the Worker Versions pinned to it, the one Worker Deployment governing its traffic, and everything activated against it. Every rule below is decided against the UID the reference RESOLVED to, never against the worker name a spec spells.</p><h3 id="one-active-deployment" tabindex="-1">One active deployment <a class="header-anchor" href="#one-active-deployment" aria-label="Permalink to &quot;One active deployment&quot;">​</a></h3><p>A <code>WorkerDeployment</code> whose resolved <code>/worker</code> UID already has one fails <code>invalid_argument</code> (400) before any mutation, on <code>apply</code> and on <code>import</code> alike. Re-applying a worker&#39;s own deployment is not a second one. Traffic moves by re-weighting the deployment a worker already has, which is what makes rollback a re-weighting rather than a mutation of a revision.</p><h3 id="deployment-integrity" tabindex="-1">Deployment integrity <a class="header-anchor" href="#deployment-integrity" aria-label="Permalink to &quot;Deployment integrity&quot;">​</a></h3><p>Before any mutation a host MUST refuse a deployment whose <code>versions[]</code></p><ul><li>weights a <code>WorkerVersion</code> whose stored <code>/worker</code> relation targets a different worker UID;</li><li>names one <code>WorkerVersion</code> twice, by resolved UID — <code>uniqueItems</code> rejects a duplicated whole entry, so one version split across two different weights is schema-valid and still says two things about one revision;</li><li>carries weights that do not sum to exactly 10000 basis points;</li><li>weights a version that is not Ready, or that an accepted delete is already removing.</li></ul><p>Each is <code>invalid_argument</code> (400): the request is well formed but states something untrue about what will run.</p><h3 id="attachment-gate" tabindex="-1">Attachment gate <a class="header-anchor" href="#attachment-gate" aria-label="Permalink to &quot;Attachment gate&quot;">​</a></h3><p>Inward activation is admitted against the worker&#39;s ACTIVE DEPLOYMENT, not against any stored version:</p><table tabindex="0"><thead><tr><th>Attachment</th><th>Required module handler</th></tr></thead><tbody><tr><td><code>WorkerCustomDomain</code></td><td><code>fetch</code></td></tr><tr><td><code>WorkerEndpoint</code></td><td><code>fetch</code></td></tr><tr><td><code>WorkerCronTrigger</code></td><td><code>scheduled</code></td></tr><tr><td><code>QueueConsumer</code></td><td><code>queue</code></td></tr></tbody></table><p>EVERY version the deployment weights MUST export that handler, because a request served by any weighted version has to find it. An absent deployment, or a weighted version that does not export the handler, fails <code>unsupported_capability</code> (422) before any mutation and the message names what is missing. A stored version is a history entry, not a running one: gating on it would admit a cron trigger against code no deployment selects.</p><p>Two attachments carry a further rule the desired schema cannot state (<a href="./../decisions/0020-the-edge-interfaces-state-their-data-and-delivery-model.html">decision 0020</a>).</p><p>A <code>WorkerCronTrigger</code>&#39;s <code>cron</code> MUST be parsed, not merely matched against the pattern the Form Definition carries. That pattern is the structural minimum a host holding only the Definition can enforce, and it admits shapes that name no schedule — <code>0 24 * * *</code>, <code>5-1 * * * *</code>, <code>*/0 * * * *</code>, <code>0 0 32 * *</code>. A host MUST refuse each of them before any mutation, on <code>validate</code>, <code>prepare</code>, and <code>apply</code> alike, with <code>invalid_argument</code> (400), and MUST accept the sub-hourly schedules the grammar exists for, <code>*/5 * * * *</code> and <code>0 * * * *</code> among them. This is the required conformance check <code>cron-grammar-enforced</code>.</p><p>An <code>AtLeastOnceQueue</code> has AT MOST ONE <code>QueueConsumer</code>. A second consumer against the same queue incarnation fails <code>invalid_argument</code> (400) before any mutation: the consumer&#39;s <code>maxRetries</code>, <code>retryDelaySeconds</code>, <code>maxConcurrency</code>, and dead-letter destination are properties of how that queue is drained, so two consumers would give one queue two of each with no rule deciding which message got which. The rule is over the queue&#39;s UID rather than its name, exactly like the deployment rule above, and removing the first consumer makes the second representable. This is the required conformance check <code>queue-single-consumer-enforced</code>.</p><h3 id="an-attachment-s-claim-is-decided-on-canonical-resolved-identity" tabindex="-1">An attachment&#39;s claim is decided on canonical, resolved identity <a class="header-anchor" href="#an-attachment-s-claim-is-decided-on-canonical-resolved-identity" aria-label="Permalink to &quot;An attachment&#39;s claim is decided on canonical, resolved identity&quot;">​</a></h3><p>Two further attachment rules are about what an attachment CLAIMS rather than about the worker it activates (<a href="./../decisions/0026-attachment-claims-are-canonical-and-acyclic.html">decision 0026</a>). Both fail <code>invalid_argument</code> (400) before any mutation, on <code>apply</code> and on <code>import</code> alike, and are re-raised when an accepted <code>202</code> commits: each is a statement about the store, and the store moves between accept and commit. All three surfaces are measured, and the two beyond <code>apply</code> are where a laxer host is most likely to differ: <code>import</code> mints a resource for something already running, so an adoption that skips the scan is how a second attachment reaches a hostname the host already answers; and at commit each of the two requests that together produce the collision was correct when it was made. The required conformance checks are <code>attachment-claim-decided-on-import</code>, which drives both rules through adoption in both polarities so a host cannot pass by refusing every adoption, and <code>attachment-claim-revalidated-at-commit</code>, which accepts a <code>202</code> while the store makes it legal, moves the store with a synchronous request that is itself legal, and requires the commit to terminate <code>invalid_argument</code>, commit nothing, and leave the synchronous resource alive.</p><p>A <code>WorkerCustomDomain</code>&#39;s <code>hostname</code> is <strong>canonicalized before it is compared and before it is stored</strong>: the trailing root dot removed and every ASCII letter lowercased. Canonicalization happens at the same entry point as declared defaults — before validation, before the spec digest, before storage and echo — so <code>API.Example.com</code>, <code>api.example.com.</code> and <code>api.example.com</code> produce byte-identical desired state, the same <code>specDigest</code>, and the same <code>generation</code>. An internationalized name travels as its <strong>A-label</strong>; the Form&#39;s <code>hostname</code> pattern admits no non-ASCII byte, so a host performs no IDNA mapping of its own and two hosts on different Unicode tables cannot canonicalize one name two ways. This is a REFUSAL and not a conversion: a U-label is refused <code>invalid_argument</code> (400) at <code>validate</code> and at <code>prepare</code>, and the A-label of the same name is accepted and stored byte-for-byte as written. A host that mapped the U-label instead would put its own Unicode table version into a portable contract, so one desired state would claim two different hostnames depending on where it was applied. This is the required conformance check <code>custom-domain-u-label-refused</code>, driven while the name is free so nothing but the Form&#39;s grammar can produce the refusal. The canonical hostname is then unique <strong>per tenant</strong>: a second <code>WorkerCustomDomain</code> claiming a hostname a live one already serves — in that space or in any other space of the same tenant — fails <code>invalid_argument</code> (400), and releasing the holder makes the claim representable. Spaces partition one tenant&#39;s resources; DNS does not partition with them, and one hostname has one answer. The tenant is the AUTHENTICATED tenant of the request, because no reference and no metadata field names one, and at commit it is the tenant the accepted mutation was admitted from. A hostname a DIFFERENT tenant serves is outside the comparison: who controls a name is authority this contract does not answer, so a host MUST accept a claim on a hostname only another tenant serves, and the refusal it gives inside a tenant MUST name that tenant&#39;s own holder and no one else&#39;s — naming another tenant&#39;s resource discloses exactly what <a href="#tenant-isolation">Tenant isolation</a> withholds. These are the required conformance checks <code>custom-domain-hostname-canonicalized</code>, <code>custom-domain-hostname-claim-unique</code>, and <code>custom-domain-hostname-claim-stops-at-the-tenant</code>; the second collides from a second space of the tenant, against an aggregate of its own, in both directions, and the third stands a second tenant&#39;s whole aggregate up and requires its claim on the served name to SUCCEED while a third claim inside that tenant is still refused.</p><p>A <code>QueueConsumer</code>&#39;s <code>deadLetterQueue</code> MUST NOT lead back to the queue the consumer drains. A destination resolving to the same queue UID is refused, and so is one closing a cycle through the dead-letter graph of any length: the graph is over queues, where the edge <code>Q -&gt; D</code> exists when the consumer of <code>Q</code> declares <code>D</code>. An exhausted message arrives at its dead-letter queue as a NEW message with its attempt count starting again at 1, so a cycle is a loop <code>maxRetries</code> cannot bound — the platform would build an infinite redelivery for the author. Because a queue has at most one consumer it has at most one outgoing edge, so a host follows a single path; the walk admits each queue UID once, so it terminates on any graph shape, including a cycle a laxer state left behind. Any length means any: a host that asks only whether the destination&#39;s own consumer points back admits <code>A -&gt; B -&gt; C -&gt; A</code>, so the required conformance check <code>dead-letter-cycle-rejected</code> closes a three-queue cycle and accepts a four-queue chain. In-degree is UNBOUNDED: one consumer is one outgoing edge, and any number of chains may end at one queue, so the same check accepts a DIAMOND and a host refusing a destination something already dead-letters to fails it.</p><h3 id="the-host-assigned-endpoint" tabindex="-1">The host-assigned endpoint <a class="header-anchor" href="#the-host-assigned-endpoint" aria-label="Permalink to &quot;The host-assigned endpoint&quot;">​</a></h3><p>The rules of this section are decided by <a href="./../decisions/0024-a-worker-is-reachable-at-a-host-assigned-address.html">decision 0024</a>.</p><p>A <code>WorkerEndpoint</code> makes one worker reachable over HTTPS without a customer-owned domain. Its desired state is the worker reference and NOTHING else: the author asks for reachability, and the address is the host&#39;s decision, in the same class as an account, a region, and a vendor subdomain (<a href="./../decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><ul><li>A host returns <code>status.outputs</code> carrying <code>hostname</code>, the DNS name it assigned, and <code>url</code>, which is exactly <code>https://</code> + that hostname + <code>/</code>. The scheme is HTTPS and TLS is not optional; there is no port and no deeper path. The assigned <code>hostname</code> is in CANONICAL form — lowercase, no trailing root dot — because a name a host produced has no earlier spelling to preserve, and the Form&#39;s own output grammar admits only that form, so the rule and the pattern a host is held to are one statement. The two members are held to that one grammar, so a hostname no <code>url</code> could be built from is not representable. The desired-state grammar of <code>WorkerCustomDomain</code> is deliberately laxer and stays so: an author writes a name and the host canonicalizes it, which is a different rule about a different value.</li><li><strong>The address is immutable for the lifetime of the endpoint&#39;s attachment UID.</strong> <code>hostname</code> and <code>url</code> MUST NOT change on deployment promotion, on status refresh, on a host&#39;s internal placement change, or on a backend migration. A host that needs to change the address deletes the endpoint and the author creates a new one — a new attachment, with a new UID, which may legitimately carry a new address. Without this rule the published address is a value a consumer may read and never store, which is not an address.</li><li>A portable author may rely on three things and no others: that a value comes back, that it is HTTPS, and that it routes to the worker&#39;s ACTIVE DEPLOYMENT. The SHAPE of the address — which label, which subdomain, which apex, how long, whether it resembles the resource name — is host detail, so a configuration MUST NOT parse the hostname, assert a suffix, or reconstruct either value from anything else it knows. Nothing measures the shape either: an address that resembles the resource name is conforming, because the endpoint&#39;s desired state carries no address for a host to have echoed.</li><li>Two endpoints on two workers carry two DIFFERENT addresses. It follows from the third guarantee rather than from any rule about the shape: one address at one path root cannot invoke the active deployments of two workers, so a host answering both with the same value has made the guarantee false for one of them.</li><li>The endpoint holds no version reference, so promotion and rollback move what answers without the endpoint being re-applied and without its address changing. &quot;Active deployment&quot; is the one this document already defines.</li><li>A worker has AT MOST ONE endpoint. A second <code>WorkerEndpoint</code> whose resolved <code>/worker</code> UID already has one fails <code>invalid_argument</code> (400) before any mutation, on <code>apply</code> and <code>import</code> alike. The rule is over the worker&#39;s UID and lives in the host because a desired schema cannot count the endpoints pointing at one worker, exactly like the one-deployment and one-consumer rules above.</li><li>A host that supports the Form but cannot offer a host-assigned hostname MUST fail <code>unsupported_capability</code> (422) before any mutation. It MUST NOT store the endpoint, and it MUST NOT answer with an address it did not assign: the whole point of the Form is that the returned address is reachable.</li><li>Deleting the endpoint never deletes the worker (the <code>attachment</code> role rule), and deleting the worker while a live endpoint pins it fails <code>dependency_in_use</code> (409) like every other relation. An endpoint therefore never outlives its worker, by refusal and ordering rather than by cascade.</li></ul><p>These are the required conformance checks <code>worker-endpoint-address-is-host-assigned</code>, <code>worker-endpoint-single-per-worker</code>, <code>worker-endpoint-follows-the-active-deployment</code>, and <code>worker-endpoint-address-is-stable-for-its-uid</code>, which drives the three triggers a black-box runner can cause — a host-side status refresh, a promotion of the worker, and a re-read — against one endpoint and compares the UID as well as the value. A placement change and a backend migration are not causable from outside a host and stay obligations below.</p><h3 id="reverse-validation-and-deletion" tabindex="-1">Reverse validation and deletion <a class="header-anchor" href="#reverse-validation-and-deletion" aria-label="Permalink to &quot;Reverse validation and deletion&quot;">​</a></h3><p>The gate holds in both directions.</p><ul><li>An apply that would leave a live dependent unserved fails <code>unsupported_capability</code> (422) before any mutation. The dependents are a live <code>WorkerCustomDomain</code> (<code>fetch</code>), a live <code>WorkerEndpoint</code> (<code>fetch</code>), a live <code>WorkerCronTrigger</code> (<code>scheduled</code>), a live <code>QueueConsumer</code> (<code>queue</code>), and a live INBOUND service binding — another Form&#39;s <code>serviceBindings</code> entry targeting this worker — which requires <code>fetch</code>.</li><li>Deleting a <code>WorkerDeployment</code> while any of those lives fails <code>dependency_in_use</code> (409). Nothing REFERENCES a deployment, so this is not the relation rule above; it is the same statement about a different edge. A host fails closed rather than degrading the dependents, and an accepted (202) delete re-runs the scan at commit time.</li></ul><h3 id="worker-readiness-and-inbound-service-bindings" tabindex="-1">Worker readiness and inbound service bindings <a class="header-anchor" href="#worker-readiness-and-inbound-service-bindings" aria-label="Permalink to &quot;Worker readiness and inbound service bindings&quot;">​</a></h3><p><code>worker.service</code> is provided by the <code>ModuleWorker</code> identity and answered by whatever its active deployment selects, so readiness is a claim about SERVICE:</p><ul><li><code>Ready=True</code> / <code>Available</code> only when the worker has an active deployment whose every weighted version exports <code>fetch</code>;</li><li><code>Ready=False</code> / <code>Provisioning</code> when it has no deployment;</li><li><code>Ready=False</code> / <code>UnsupportedCapability</code> when its deployment serves no <code>fetch</code>.</li></ul><p>Both false cases carry a <code>hostReason</code> naming the worker and what is missing. A <code>module-worker.service</code> binding to a worker in either state is refused at BIND time with <code>unsupported_capability</code> (422), rather than stored and reported not-Ready: a stored binding that projects nothing is a declared capability no host can keep.</p><p>The worker is not addressed by any of the mutations that move it between these three states, so this is a representation rendered from another resource: a host MUST advance the worker&#39;s <code>metadata.revision</code>, and MUST NOT move its <code>metadata.generation</code>, when a deployment change flips the condition (see <a href="#resource-identity">Resource identity</a>).</p><h3 id="the-environment-namespace-is-single" tabindex="-1">The environment namespace is single <a class="header-anchor" href="#the-environment-namespace-is-single" aria-label="Permalink to &quot;The environment namespace is single&quot;">​</a></h3><p>Within one <code>WorkerVersion</code>, <code>vars</code> keys, <code>requiredSensitiveVars</code> entries, and every binding <code>name</code> across every binding list are projected into ONE runtime environment object, so their union MUST be unique. A collision fails <code>invalid_argument</code> (400) before any mutation, and a client SHOULD refuse it at plan time so the author sees it without a round trip. The schema cannot state it: <code>uniqueItems</code> compares whole objects, so two bindings agreeing only on <code>name</code> are distinct, and no keyword relates a property&#39;s keys to a sibling array&#39;s element member. A host discovers the binding lists from the <code>x-takoform-binding</code> annotation the desired schema already carries.</p><h2 id="lifecycle-capabilities" tabindex="-1">Lifecycle capabilities <a class="header-anchor" href="#lifecycle-capabilities" aria-label="Permalink to &quot;Lifecycle capabilities&quot;">​</a></h2><p><code>lifecycleCapabilities</code> is a claim about what a host can actually be asked to do, so it is derived from the Form&#39;s own declared fields rather than from its role. The base set every Form declares is exactly <code>create</code>, <code>read</code>, <code>delete</code>, <code>import</code>, <code>observe</code>. <code>update</code> is added only when the Form has at least one mutable desired field — a field that is not immutable, on a Form whose role is not <code>revision</code>. A Form with no field at all, or whose every field is immutable, therefore declares no <code>update</code>.</p><p>The rule is enforced on the wire in both directions. A host MUST refuse a spec-CHANGING apply to an existing resource whose Form Definition omits <code>update</code>, failing <code>invalid_argument</code> before any mutation; a client MUST plan a replacement rather than an in-place change for such a Form.</p><h2 id="portable-defaults" tabindex="-1">Portable defaults <a class="header-anchor" href="#portable-defaults" aria-label="Permalink to &quot;Portable defaults&quot;">​</a></h2><p>An optional desired property carries its portable meaning in its own schema: the Form Definition declares a JSON Schema <code>default</code> on that property inside <code>desiredSchema</code>. That default is normative, not advisory.</p><p>A host MUST materialize every declared top-level default into the desired spec at the entry point of <code>validate</code>, <code>prepare</code>, <code>apply</code>, and <code>import</code> — before the spec is validated, digested, stored, or echoed. Materialization fills only absent properties; a property that is present keeps its written value, even when that value equals the default. It follows that:</p><ul><li>the effective spec IS the wire spec: there is no second, host-private document a client cannot see;</li><li><code>specDigest</code> is the digest of the MATERIALIZED spec;</li><li>omitting a defaulted property and writing its default are one desired state: same <code>specDigest</code>, same <code>metadata.generation</code>, no update;</li><li>a client that sends an unmaterialized spec MUST accept the materialized echo from <code>prepare</code>, <code>apply</code>, <code>import</code>, and <code>read</code> as its own desired state.</li></ul><p>An optional property with no declared default is only legitimate when its ABSENCE is itself the portable semantics, and the property&#39;s <code>description</code> must then state what the absent case does.</p><h2 id="declared-outputs" tabindex="-1">Declared outputs <a class="header-anchor" href="#declared-outputs" aria-label="Permalink to &quot;Declared outputs&quot;">​</a></h2><p>The rules of this section are decided by <a href="./../decisions/0025-declared-outputs-are-a-typed-contract.html">decision 0025</a>.</p><p>A Form Definition MAY declare an <code>outputSchema</code>: the closed Draft 2020-12 contract of the host-computed values it publishes. Every declared member is required and the object carries <code>additionalProperties: false</code>, because an output a host may omit forces every consumer to invent a fallback, and an undeclared member is a value the contract never described.</p><p>A host is held to it in both directions, which is the rule the wire schema already states through <code>x-takoform-requiredWhen</code> and <code>x-takoform-omittedWhen</code>:</p><ul><li>for a Form that declares an <code>outputSchema</code>, <code>status.outputs</code> is PRESENT, validates against that schema, and carries exactly its members;</li><li>for a Form that declares none, <code>status.outputs</code> is OMITTED — not an empty object.</li></ul><p>This is the required conformance check <code>form-declared-outputs-are-exact</code>, driven across a Form that declares outputs and Forms that declare none, because a host returning an empty document everywhere would satisfy only the first half. Each returned value is measured against the declared schema — its type, its anchored pattern, its bounds — rather than against an assumption about it: a check that only asked for a non-empty string would accept <code>hostname: &quot;not a hostname&quot;</code> and reject an integer output the authoring model permits. The conformance corpus pins the whole declared schema for that reason, since no wire surface serves one.</p><p>An output is not desired state. It carries no default, no immutability, and no cross-resource reference: those describe what an author asks for, and an output is what the host answers. A change to an output moves <code>metadata.revision</code> and never <code>metadata.generation</code>, like every other representation change.</p><p>The <code>outputSchema</code> is not served on the wire. The form-definition response is a closed document carrying identity, display name, description, and <code>desiredSchema</code>, and its bytes are immutable (<a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>), so a client learns a Form&#39;s output contract from the Form Package it installs.</p><p>The Terraform and OpenTofu provider projects each declared output as a typed computed attribute, and retains <code>outputs_json</code> — carrying the WHOLE document, unnarrowed — as the way to reach an output no schema describes. It writes null for a declared output only where no representation exists — the state an accepted-but-unfinished mutation leaves behind — and fails an ordinary create, update, or refresh whose response omits a declared output or returns it with the wrong type, naming the output and what was wrong.</p><h2 id="long-running-operations" tabindex="-1">Long-running operations <a class="header-anchor" href="#long-running-operations" aria-label="Permalink to &quot;Long-running operations&quot;">​</a></h2><p>Create, update, delete, import, and artifact commit MAY return <code>202 Accepted</code> with an Operation envelope (<a href="/schemas/operations/v1alpha1/operation.schema.json"><code>../schemas/operation-v1alpha1.schema.json</code></a>) instead of the terminal representation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  {api}/operations/{id}</span></span>
<span class="line"><span>POST {api}/operations/{id}/cancel</span></span></code></pre></div><p>Clients poll with <code>Retry-After</code> when present, otherwise exponential backoff with full jitter, under an overall deadline. The contract guarantees only that an operation ID is stable, that the host keeps it addressable at <code>GET {api}/operations/{id}</code> while the operation record exists (afterwards the closed outcome is <code>operation_not_found</code>), and that a terminal operation replays its terminal state instead of re-executing. A terminal Operation carries exactly one of <code>result</code> or <code>error</code>. Cancel is honored only for safely stoppable operations; an already-terminal operation replays its terminal state. <code>operation_not_found</code> (404) and <code>operation_cancelled</code> (409) are the closed outcomes; <code>deadline_exceeded</code> (504) reports a host-side deadline.</p><p>A <code>202</code> accepts a mutation to <strong>one resource</strong>, and the commit is bound to that one (<a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>). A host records the target&#39;s exact <code>formRef</code> and <code>metadata.uid</code> beside the fence the mutation was accepted under, and at commit time resolves through that record rather than re-deriving a target from the name the request addressed. A name is unique per kind and reusable, and a re-created resource starts at generation 1 and at revision 1, so whichever counter a fence names, a target removed out of band and re-created — under the same contract or under another definition version of it — presents a NEW incarnation behind the same address that satisfies the fence the original was accepted under. When the name is held by a different incarnation the operation terminates <code>uid_mismatch</code> (409); when nothing holds it, <code>resource_not_found</code> (404). Neither commits anything, and neither is retryable: no wait turns one incarnation back into another. A create is fenced against the free name rather than against an incarnation, so it pins none and <code>If-None-Match: *</code> decides at commit as it always did. This is the required conformance check <code>async-commit-binds-the-accepted-identity</code>.</p><p>An operation id is a resumption handle, <strong>not a capability</strong>. A host records the authenticated tenant and principal that the mutation was accepted from, and answers <code>GET {api}/operations/{id}</code> and <code>POST {api}/operations/{id}/cancel</code> from any other tenant or principal with <code>operation_not_found</code> (404) — the same answer an id that never existed gets. <code>permission_denied</code> would confirm that the id names a real operation, which is the one fact a stranger holding a guessed or leaked id is trying to learn (<a href="./../decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>). This is the required conformance check <code>operation-bound-to-its-creating-principal</code>.</p><p>&quot;While the record exists&quot; is a retention window, not an ordering: a host MUST NOT drop a terminal operation merely because the system moved on. As long as the record is retained, the ID stays addressable and its terminal state replays byte-identically after the resource it names has been mutated again and after other operations have been accepted and settled. This is the required conformance check <code>operation-resumable-after-settlement</code>, and it is what makes a persisted operation ID a usable handle rather than one whose value depends on timing.</p><p>A client that persists the ID resumes from it (<a href="./../decisions/0017-provider-state-survives-form-evolution-and-interruption.html">decision 0017</a>): the Terraform/OpenTofu provider records it as <code>pending_operation_id</code> and consults it BEFORE it reads the resource, because on a host that commits the resource only when the operation commits, a <code>resource_not_found</code> during that window means &quot;not yet&quot;, not &quot;deleted&quot;. A terminal success is verified against the exact identity before anything is adopted, and an expired record defers to an exact resource read rather than being read as failure.</p><h2 id="artifacts" tabindex="-1">Artifacts <a class="header-anchor" href="#artifacts" aria-label="Permalink to &quot;Artifacts&quot;">​</a></h2><p>The content-addressed upload API is <a href="./../artifact-transport/"><code>../artifact-transport/</code></a>. The artifact endpoints share the lane&#39;s auth, idempotency, and error taxonomy.</p><p>The desired state of a bundle-shaped revision resource is the <strong>manifest digest and nothing else</strong>: the committed artifact manifest describes the bytes, so the manifest and the desired spec are never two spellings of the same facts. A host MUST therefore resolve the referenced manifest before it mutates anything, on apply and on import alike, and fail closed when</p><ul><li>the digest names no committed manifest the caller&#39;s tenant holds — <code>artifact_missing</code> (404). Resolution is the same per-tenant question the artifact read surfaces ask, so a manifest another tenant committed is answered exactly as an uncommitted digest is;</li><li>the stored manifest&#39;s RFC 8785 canonical digest differs from the referenced digest, its document is undecodable, or its <code>kind</code> is not the kind the Form requires — <code>artifact_invalid</code> (400);</li><li>the manifest violates any rule of <a href="./../artifact-transport/"><code>../artifact-transport/</code></a>, including its per-kind exclusivity, its closed media types, and the host&#39;s published <code>limits</code> — <code>artifact_invalid</code> (400).</li></ul><p>A committed manifest and its blobs MUST remain readable while any resource references the manifest. Abandoning an unrelated upload session, or garbage-collecting staged blobs, MUST NOT make a referenced artifact unresolvable.</p><h3 id="a-bundle-s-modules-are-what-the-runtime-can-load" tabindex="-1">A bundle&#39;s modules are what the runtime can load <a class="header-anchor" href="#a-bundle-s-modules-are-what-the-runtime-can-load" aria-label="Permalink to &quot;A bundle&#39;s modules are what the runtime can load&quot;">​</a></h3><p>The module media types a <code>WorkerBundle</code> manifest admits are exactly the LOADABLE set <code>worker.runtime@1.0.0</code> imports — <code>application/javascript+module</code>, <code>text/plain</code>, <code>application/octet-stream</code>, <code>application/wasm</code> — plus the AUXILIARY set a bundle carries and the graph never imports, today <code>application/source-map+json</code> alone. <code>application/json</code> is in neither: this ABI version loads none, and the published manifest enum never admitted one (<a href="./../decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>).</p><p>A host MUST refuse a <code>WorkerBundle</code> whose <code>mainModule</code> names an auxiliary module, before commit and before any mutation that references the manifest, with <code>artifact_invalid</code> (400) — and MUST NOT refuse a bundle merely for CARRYING one. The published manifest schema states the union in one enum and cannot relate <code>mainModule</code> to the media type of the module it names, so the split is host-enforced under <a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a> and proved by the required conformance check <code>bundle-main-module-is-loadable</code>. The corresponding runtime obligation — an import resolving to an auxiliary module fails <code>unsupported_media_type</code> — is behavior no desired-state runner observes, and stays a host obligation with the rest of the ABI.</p><h3 id="upload-sessions-are-owned" tabindex="-1">Upload sessions are owned <a class="header-anchor" href="#upload-sessions-are-owned" aria-label="Permalink to &quot;Upload sessions are owned&quot;">​</a></h3><p>An upload id is a handle bound to the tenant and principal that started the session, exactly as an operation id is. Continuing it (<code>PUT {api}/artifacts/uploads/{uploadId}/blobs/{sha256}</code>), committing it, and abandoning it from any other tenant or principal all fail <code>artifact_missing</code> (404). Abandoning an id the caller does not hold fails the same way whether it never existed or belongs to someone else: answering <code>204</code> for one and <code>404</code> for the other would make the difference observable, which is the disclosure the rule exists to prevent. This is the required conformance check <code>upload-session-bound-to-its-creating-principal</code>.</p><h3 id="a-content-address-is-not-a-capability" tabindex="-1">A content address is not a capability <a class="header-anchor" href="#a-content-address-is-not-a-capability" aria-label="Permalink to &quot;A content address is not a capability&quot;">​</a></h3><p>A digest names bytes; it does not entitle a caller to them (<a href="./../decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>). <code>GET {api}/artifacts/{manifestDigest}</code> and <code>HEAD {api}/artifacts/blobs/{sha256}</code> answer only a caller whose TENANT already holds that address — by having uploaded the bytes, or by having committed a manifest that names them. Any other tenant is answered <code>artifact_missing</code> (404) for a manifest and <code>404</code> for a blob, even for a digest that exists. It follows that <code>missingBlobs</code> is answered per tenant and not per byte store: reporting a blob as already present because a different tenant uploaded it would hand over bytes on the strength of a digest.</p><p>A host MAY still deduplicate physically — one stored copy per content address, however many tenants hold it. Two tenants that upload the same bytes and commit the same manifest see the same immutable identity, and neither one&#39;s abandon or garbage collection may take the bytes away from the other. This is the required conformance check <code>artifact-digest-is-not-a-capability</code>.</p><p>The rule governs <strong>using</strong> an address as well as reading one. Wherever a host resolves a manifest or a blob on behalf of a request — above all the referenced manifest of a bundle-shaped desired state — it asks the same per-tenant holding question, so a caller who merely learns a digest cannot apply or import their way to another tenant&#39;s artifact. The refusal is the ordinary <code>artifact_missing</code> (404), raised before any mutation on apply and import alike and re-raised when a 202 commits, and it MUST NOT distinguish &quot;exists but is not yours&quot; from &quot;does not exist&quot;: a distinguishable refusal is the existence oracle the read rule removes. Holding is the tenant&#39;s, so a manifest one principal uploaded is referenceable by another principal of the same tenant, and a tenant that supplies the same bytes itself references the same immutable identity like any other holder. This is the required conformance check <code>manifest-reference-is-not-a-capability</code>.</p><h2 id="support-profiles" tabindex="-1">Support profiles <a class="header-anchor" href="#support-profiles" aria-label="Permalink to &quot;Support profiles&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET {api}/support/forms</span></span>
<span class="line"><span>GET {api}/support/forms/{formGroup}/{formVersion}/{kind}/{definitionVersion}</span></span>
<span class="line"><span>GET {api}/support/interfaces/{name}/{version}</span></span>
<span class="line"><span>GET {api}/support/bindings/{name}/{version}</span></span></code></pre></div><p>Responses validate against <a href="/schemas/support/v1alpha1/host-support-profile.schema.json"><code>../schemas/host-support-profile-v1alpha1.schema.json</code></a>. A profile declares supported exact refs, closed capability subsets (<code>supportedEnums</code>), inclusive ranges (<code>supportedRanges</code>), supported binding contracts, and numeric limits. Price, SKU, region, quota, and commercial policy MUST NOT appear; those remain Service Offering data outside this API.</p><p>A host that supports the Edge Platform Family&#39;s <code>ModuleWorker</code> MUST advertise the ES Module Worker runtime ABI contract <code>worker.runtime@1.0.0</code> at the exact <code>schemaDigest</code> that Form&#39;s <code>providedInterfaces</code> names, and MUST advertise the <code>WorkerVersion</code> <code>handlers</code> enum as exactly the handler vocabulary that contract defines. It MUST NOT advertise a <code>compatibilityDate</code> range or a <code>compatibilityFlags</code> enum: runtime behavior is stated by implementing an exact contract, not by a token no registry interprets (<a href="./../decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>). A <code>WorkerVersion</code> declaring a handler the runtime contract does not define MUST be refused before any mutation, and so MUST a <code>WorkerVersion</code> declaring a handler the main module of the <code>WorkerBundle</code> it references does not export: <code>loadModule</code> fails that version with <code>handler_not_exported</code> before any traffic arrives, so storing it would leave the attachment gate above admitting a cron trigger or a queue consumer against a handler that does not exist. The first is decidable from the spec alone and is refused on <code>validate</code>, <code>prepare</code>, and <code>apply</code> alike; the second needs the bundle relation, the committed manifest, and the module bytes, so it is refused before any mutation on <code>apply</code> and <code>import</code> alike and re-raised when a 202 commits — <code>invalid_argument</code> (400) in both cases, because the request is well formed and states something untrue about what will run. These are the required conformance checks <code>module-worker-runtime-contract-advertised</code>, <code>undeclared-runtime-handler-rejected</code>, and <code>declared-handler-not-exported-rejected</code>.</p><h3 id="what-the-lane-proves-and-what-stays-a-host-obligation" tabindex="-1">What the lane proves, and what stays a host obligation <a class="header-anchor" href="#what-the-lane-proves-and-what-stays-a-host-obligation" aria-label="Permalink to &quot;What the lane proves, and what stays a host obligation&quot;">​</a></h3><p><code>worker.runtime@1.0.0</code> fixes far more than a black-box lifecycle runner can observe, so the split is stated rather than implied.</p><p>Proven by required checks:</p><ul><li>the host advertises the runtime contract at the EXACT pinned <code>schemaDigest</code>, and supports the exact <code>ModuleWorker</code> Form line that provides it;</li><li>the <code>WorkerVersion</code> <code>handlers</code> enum it advertises is exactly that contract&#39;s vocabulary, and it advertises no <code>compatibilityDate</code> range or <code>compatibilityFlags</code> enum;</li><li>a version declaring a handler outside the vocabulary is refused, and one declaring only defined handlers is still accepted;</li><li>a version declaring a handler its referenced module does not export is refused against a corpus-pinned bundle, and one declaring only exported handlers is still accepted;</li><li>every inward-activation attachment is gated on the handler its events invoke, in both directions;</li><li>a <code>WorkerEndpoint</code> is answered with a complete HTTPS address the host assigned, in canonical form and with the two published members built from one hostname; that address is still the same address, under the same UID, after a host-side status refresh, a promotion of the worker it serves, and a re-read; and a second endpoint against one worker is refused.</li></ul><p>Obligations a conforming host MUST meet that this lane does NOT prove, because proving them means executing the module rather than driving the Host API:</p><ul><li>the default export&#39;s shape, the three-argument handler signatures, and that a returned promise is awaited;</li><li><code>handler_not_exported</code> for an ARBITRARY module — the lane drives bundles whose exports the corpus pinned, so what it proves is that a host refuses the version when it knows, not that it derives the export set from any bytes an author uploads;</li><li>request and response bodies streaming rather than buffering;</li><li><code>env</code> carrying exactly the declared names and nothing else portable;</li><li><code>ctx.waitUntil</code> holding the isolate open, and a rejected task never changing an already-sent response;</li><li>an uncaught throw becoming a host-generated 500 in <code>fetch</code> and a failed invocation in <code>scheduled</code> and <code>queue</code>;</li><li>the <code>globals</code> floor, the loadable module media types, and that an import resolving to an auxiliary module fails <code>unsupported_media_type</code> rather than linking source-map evidence into the graph;</li><li>that a request to a <code>WorkerEndpoint</code>&#39;s published address actually ARRIVES at the worker. The lane drives desired state and sends no traffic, so what it proves is that a host answers with a complete HTTPS address it assigned and keeps that address stable across a promotion — not that anything is listening on it. Nor can it prove the refusal branch: a black-box runner cannot take the address-assignment capability away from the host under test, so <code>unsupported_capability</code> (422) for a host that cannot assign one is stated normatively and left to that host to honor.</li></ul><p>Nothing the ABI declares is unmeasurable any more. <code>worker.runtime@1.0.0</code> used to declare a <code>tail</code> handler no resource in this family could activate, so no run could observe it and two hosts could implement it differently with nothing able to detect the divergence; the handler was removed rather than left in a published-shaped contract nothing reaches, and the runtime corpus now REFUSES a declared handler with no check measuring it, so the property is enforced rather than described. <code>tail</code> returns with the attachment that makes it observable and a new exact runtime Interface version, never as a bare handler (<a href="./../decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>).</p><p>Those are stated normatively in the contract&#39;s own descriptions and proven by its behavior fixtures, which a runtime conformance run executes against a real isolate (<a href="./../interface-contract/"><code>../interface-contract/</code></a>). That run is <a href="../../conformance/runtime-abi-v1/contract.json"><code>../../conformance/runtime-abi-v1/</code></a>, whose runner drives a worker deployed from its own byte-pinned bundle and a disposable adapter over the runtime&#39;s module loader; it is a separate corpus, runner, and command from this lane precisely because the subjects differ (<a href="./../decisions/0023-the-runtime-abi-is-measured-separately-from-the-control-plane.html">decision 0023</a>). A host that passes this lane has not thereby proven it implements the ABI; it has proven it says which ABI it implements and holds desired state to it.</p><p>The same split covers the four data-plane contracts — <code>edge.kv</code>, <code>edge.objects</code>, <code>edge.sql</code>, and <code>edge.queue</code> — and <code>worker.service</code>, whose whole delivery model is a claim about bytes moving between two workers: that neither body is buffered, that an absent body is distinguishable from an empty one and from one whose length the writer does not yet know, that a length the head DOES declare is one the bytes keep, that backpressure and cancellation propagate, that a request abort and a response abort are different observable outcomes, that a callee exception arrives as a complete host-generated 500 rather than a hung call, and that a call which could not be dispatched fails rather than answering with a status. This lane drives desired state and never moves a byte of application data (<a href="./../decisions/0020-the-edge-interfaces-state-their-data-and-delivery-model.html">decision 0020</a>).</p><p>Proven by required checks:</p><ul><li>the host advertises each of the four contracts at the EXACT pinned <code>schemaDigest</code>, which is what turns &quot;this host has a KV store&quot; into a statement about a consistency model, a value model, an error vocabulary, and a set of limits (<code>edge-interface-contracts-advertised</code>);</li><li>a <code>WorkerCronTrigger</code> whose expression is a shape rather than a schedule is refused, and the sub-hourly schedules the grammar exists for are accepted (<code>cron-grammar-enforced</code>);</li><li>a second <code>QueueConsumer</code> against one queue is refused, and the same consumer is accepted once the first is gone (<code>queue-single-consumer-enforced</code>);</li><li>a <code>WorkerCustomDomain</code> written in any spelling of one DNS name is stored under the canonical one, and a second attachment claiming it — in either spelling — is refused while the first lives and accepted once it is gone (<code>custom-domain-hostname-canonicalized</code>, <code>custom-domain-hostname-claim-unique</code>);</li><li>a hostname another TENANT serves is claimable, both claims stay live under two uids, releasing one leaves the other alone, and inside either tenant a second claim is still refused without naming anyone else&#39;s resource (<code>custom-domain-hostname-claim-stops-at-the-tenant</code>);</li><li>a <code>QueueConsumer</code> whose dead-letter destination resolves to its own queue, or closes a cycle through another consumer&#39;s, is refused, and an acyclic destination is accepted, including one that shares a destination with another chain (<code>dead-letter-cycle-rejected</code>).</li></ul><p>Obligations a conforming host MUST meet that this lane does NOT prove, because proving them means exercising the data plane rather than driving the Host API:</p><ul><li><strong><code>edge.kv</code> convergence.</strong> That a write eventually becomes visible at every location. One client cannot observe cross-location convergence at all, which is why the contract&#39;s deterministic fixtures assert only facts no write has to converge for. The obligation is that convergence happens, that a host&#39;s own convergence target is stated in its Host Support Profile, and that the contract&#39;s other reading — read-your-writes — is NOT provided and must not be relied on.</li><li><strong>The encoded-bytes value model.</strong> That <code>maxValueBytes</code> and <code>maxMessageBytes</code> bound the DECODED length, that <code>maxKeyBytes</code> bounds a key&#39;s UTF-8 encoding, and that undecodable base64 is refused.</li><li><strong><code>edge.objects</code> streaming, ranges, conditionals, and multipart.</strong> That a body is never buffered into a JSON member, that a ranged <code>get</code> returns exactly the requested subrange of one object version, that a failed precondition changes nothing, and that a multipart upload assembles its parts atomically or not at all. The contract&#39;s fixtures state the first three as traces a runtime conformance run executes; multipart cannot be a static trace, because its steps depend on part etags the host mints while the trace runs.</li><li><strong><code>edge.sql</code> losslessness and atomicity.</strong> That a 64-bit INTEGER and a BLOB round-trip unchanged, that an out-of-range integer is refused, that a writing statement submitted through <code>query</code> is refused, and that a failed transaction applies nothing.</li><li><strong><code>edge.queue</code> delivery.</strong> That a <code>messageId</code> is stable across redeliveries, that <code>attempts</code> counts them, that the first delivery does not count toward <code>maxRetries</code>, that an uncaught handler exception retries every message not already acknowledged, and that a dead-lettered message arrives as a new message with <code>attempts</code> starting again at 1. All of it needs a consumer and the passage of time, neither of which a desired-state runner has.</li></ul><p>Those are stated normatively in each contract&#39;s own descriptions and proven by its behavior fixtures wherever a fixture can prove them.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>The closed taxonomy extends v1alpha2 with <code>rate_limited</code> (429), <code>deadline_exceeded</code> (504), <code>operation_cancelled</code> (409), <code>operation_not_found</code> (404), <code>dependency_in_use</code> (409), <code>deletion_protected</code> (409), <code>artifact_missing</code> (404), <code>artifact_invalid</code> (400), <code>unsupported_capability</code> (422), <code>migration_required</code> (409), <code>uid_mismatch</code> (409), <code>revision_conflict</code> (412), and <code>generation_conflict</code> (412). Only <code>resource_busy</code>, <code>backend_unavailable</code>, <code>rate_limited</code>, and <code>deadline_exceeded</code> may be <code>retryable: true</code>; <code>Retry-After</code> is honored when present. The v1alpha2 codes <code>resource_version_conflict</code>, <code>interface_identity_ambiguous</code>, and <code>interface_instance_ambiguous</code> do not exist in this lane: version conflicts split into the revision/generation pair, and the v1alpha2 interface projection is replaced by exact Interface contracts (<a href="./../interface-contract/"><code>../interface-contract/</code></a>).</p>`,162)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
